// Derived files, generated by the client: previews/<pageId>.svg, cover.png, pdftext.json
// (port of Derived.php). No revision check: they are rebuilt from the note at any time.
import { ApiError, assertId, nfc, cpSlice, toText, toBytes, isArr, isInt } from './util.js';
import * as Attachments from './attachments.js';

const MAX_SVG = 8 * 1024 * 1024;
const MAX_PNG = 4 * 1024 * 1024;

export async function savePreview(ctx, noteId, pageId, bytes) {
  assertId(noteId);
  if (!/^pg-[0-9a-f]{8}$/.test(pageId)) throw new ApiError(400, 'bad_page', 'Pagina non valida.');
  if (!bytes.length || bytes.length > MAX_SVG) throw new ApiError(413, 'too_large', 'Anteprima vuota o troppo grande.');
  const svg = toText(bytes);
  const head = svg.slice(0, 200).trimStart();
  if (!head.startsWith('<svg') && !head.startsWith('<?xml')) throw new ApiError(400, 'bad_svg', "L'anteprima non è un SVG.");
  // The previews are meant to be opened outside the app: refuse anything active.
  if (/<script|<foreignObject|<[^>]*\son[a-z]+\s*=|<[^>]*href\s*=\s*["']\s*javascript:/i.test(svg)) {
    throw new ApiError(400, 'bad_svg', "L'anteprima contiene elementi non ammessi.");
  }
  const { fs, index } = ctx;
  const rel = await index.notePath(noteId);
  const pages = (await fs.readJson(`${rel}/pages.json`)) ?? { pages: [] };
  const ids = new Set(pages.pages.map((p) => p.id));
  if (!ids.has(pageId)) throw new ApiError(404, 'page_not_found', 'Pagina non trovata (forse è stata eliminata).');
  await fs.writeAtomic(`${rel}/previews/${pageId}.svg`, bytes);
  // Previews of pages that no longer exist are derived files: safe to remove.
  for (const name of await fs.list(`${rel}/previews`)) {
    const m = name.match(/^(pg-[0-9a-f]{8})\.svg$/);
    if (m && !ids.has(m[1])) await fs.unlink(`${rel}/previews/${name}`);
  }
}

const PNG_SIG = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];

export async function saveCover(ctx, noteId, bytes) {
  assertId(noteId);
  if (bytes.length < 8 || bytes.length > MAX_PNG || PNG_SIG.some((v, i) => bytes[i] !== v)) {
    throw new ApiError(400, 'bad_png', 'La copertina deve essere un PNG (massimo 4 MB).');
  }
  const { fs, index } = ctx;
  const rel = await index.notePath(noteId);
  await fs.writeAtomic(`${rel}/cover.png`, bytes);
  await index.putNote(noteId, rel, (await index.noteEntry(noteId)).parentId);
  await index.save();
}

/**
 * PUT /api/notes/{id}/pdftext/{file}: text of a PDF's pages, extracted by the client with
 * pdf.js, merged into pdftext.json (one entry per PDF page) for search.
 */
export async function savePdfText(ctx, noteId, file, input) {
  assertId(noteId);
  Attachments.assertName(file);
  if (!isArr(input) || !Array.isArray(input.pages) || input.pages.length > 5000) {
    throw new ApiError(400, 'bad_pdftext', 'Testo del PDF non valido.');
  }
  const added = [];
  let bytes = 0;
  for (const p of input.pages) {
    if (!isArr(p) || !isInt(p.pageIndex) || p.pageIndex < 0 || typeof p.text !== 'string') {
      throw new ApiError(400, 'bad_pdftext', 'Testo del PDF non valido.');
    }
    const text = cpSlice(nfc(p.text), 0, 100000);
    bytes += toBytes(text).length;
    added.push({ file, pageIndex: p.pageIndex, text });
  }
  if (bytes > 20 * 1024 * 1024) throw new ApiError(413, 'too_large', 'Testo del PDF troppo grande.');
  const { fs, index } = ctx;
  const rel = await index.notePath(noteId);
  const cur = (await fs.readJson(`${rel}/pdftext.json`)) ?? {};
  // Older entries without "file" belonged to the top-level file.
  let pages = (cur.pages || []).filter((p) => isArr(p) && (p.file ?? cur.file ?? null) !== file)
    .map((p) => ({ ...p, file: p.file ?? cur.file ?? null }));
  pages = pages.concat(added);
  await fs.writeJson(`${rel}/pdftext.json`, { version: 1, file: pages[0]?.file ?? file, pages });
  return { ok: true, pages: added.length };
}

export async function readCover(ctx, noteId) {
  assertId(noteId);
  const bytes = await ctx.fs.read(`${await ctx.index.notePath(noteId)}/cover.png`);
  if (bytes === null) throw new ApiError(404, 'no_cover', 'Nessuna copertina.');
  return bytes;
}
